1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strconv"
10		"unicode/utf8"
11	)
12	
13	// EvalReason is the machine-readable outcome of a flag evaluation.
14	type EvalReason string
15	
16	const (
17		EvalDisabled EvalReason = "disabled"
18		EvalRule     EvalReason = "rule"
19		EvalDefault  EvalReason = "default"
20	)
21	
22	// Condition is one predicate over an evaluation context.
23	type Condition struct {
24		Attribute string
25		Op        string
26		// strVal 用于 eq；inVal 用于 in（至少一项）。
27		strVal string
28		inVal  []string
29	}
30	
31	// Rule groups conditions that must all hold; on match the flag takes Value.
32	type Rule struct {
33		ID         string
34		Value      bool
35		Conditions []Condition
36	}
37	
38	// Flag is one feature toggle with its default and ordered rules.
39	type Flag struct {
40		Key     string
41		Enabled bool
42		Default bool
43		Rules   []Rule
44	}
45	
46	// Config is a validated feature flag configuration.
47	type Config struct {
48		Flags []Flag
49	}
50	
51	// EvalResult is the deterministic outcome of evaluating one flag.
52	type EvalResult struct {
53		Key    string     `json:"key"`
54		Value  bool       `json:"value"`
55		Reason EvalReason `json:"reason"`
56		RuleID *string    `json:"ruleId"`
57	}
58	
59	// Equals reports whether two evaluation results are identical.
60	func (r EvalResult) Equals(other EvalResult) bool {
61		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
62			return false
63		}
64		if (r.RuleID == nil) != (other.RuleID == nil) {
65			return false
66		}
67		if r.RuleID != nil && *r.RuleID != *other.RuleID {
68			return false
69		}
70		return true
71	}
72	
73	// Context is a validated map of attribute names to string values.
74	type Context struct {
75		values map[string]string
76	}
77	
78	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
79	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
80	func LoadConfig(path string) (*Config, error) {
81		raw, err := os.ReadFile(path)
82		if err != nil {
83			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
84		}
85		return ParseConfig(raw)
86	}
87	
88	// LoadContext reads and validates a UTF-8 JSON context file.
89	func LoadContext(path string) (*Context, error) {
90		raw, err := os.ReadFile(path)
91		if err != nil {
92			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
93		}
94		return ParseContext(raw)
95	}
96	
97	// unmarshalStrictJSON 严格解码一个 UTF-8 JSON 文档到 any，并保持与
98	// json.Unmarshal 相同的单文档语义：文档之后只允许空白，不允许第二个值。
99	// 使用 json.Decoder + UseNumber：数字按原文保留为 json.Number，而不是强制
100	// 转成 float64——语法合法但超出浮点范围的数字（如 1e400、由 1 后接 400 个 0
101	// 组成的整数）不应被当成“JSON 无效”，它们是合法的 JSON 数字，由后续的值
102	// 类型检查以所属字段的类型错误报告。
103	func unmarshalStrictJSON(raw []byte) (any, error) {
104		dec := json.NewDecoder(bytes.NewReader(raw))
105		dec.UseNumber()
106		var doc any
107		if err := dec.Decode(&doc); err != nil {
108			return nil, err
109		}
110		// Decoder 本身容忍文档之后的额外 JSON 值，需显式补回 Unmarshal 的严格性。
111		offset := int(dec.InputOffset())
112		var extra any
113		if err := dec.Decode(&extra); err != io.EOF {
114			if err != nil {
115				return nil, err
116			}
117			for offset < len(raw) && isJSONWhitespace(raw[offset]) {
118				offset++
119			}
120			c := byte(0)
121			if offset < len(raw) {
122				c = raw[offset]
123			}
124			return nil, fmt.Errorf("invalid character %q after top-level value", c)
125		}
126		return doc, nil
127	}
128	
129	// isJSONWhitespace 报告 b 是否为 JSON 允许的空白字节。
130	func isJSONWhitespace(b byte) bool {
131		return b == ' ' || b == '\t' || b == '\n' || b == '\r'
132	}
133	
134	// parseJSONDocument 执行配置与上下文两类输入共同维护的文档格式校验，使两份
135	// JSON 对同一组格式规则给出一致的接受结果与错误定位。检查按固定先后顺序报告
136	// 原文中的第一处问题：
137	//  1. 非法 UTF-8 字节——最先检查，不被其后任何错误遮住；
138	//  2. 不能组成完整字符的 \uXXXX 转义（字段名与字符串值同等检查）——先于
139	//     重复字段，避免 encoding/json 把孤立代理项静默替换成 U+FFFD 后误判重复；
140	//  3. 同一对象内的重复字段——先于业务字段问题；
141	//  4. JSON 语法与单文档边界：只接受一个顶层值，完整文档后只允许空白，
142	//     第二个值或其他尾随内容一律拒绝；
143	//  5. 顶层必须是一个 JSON 对象。
144	//
145	// 这一步只判定文档格式：数字一律按原文保留（json.Number），语法合法但超出
146	// 浮点范围的大数字不在此拒绝；具体字段的类型/必填/唯一性属于各自的业务规则，
147	// 由调用方在取得 root 后按配置或上下文的约定继续校验。label 是本文档在错误
148	// 信息中的名字（"config" 或 "context"）。
149	func parseJSONDocument(raw []byte, label string) (map[string]any, error) {
150		if !utf8.Valid(raw) {
151			return nil, fmt.Errorf("%s: file is not valid UTF-8", label)
152		}
153		if err := rejectInvalidUnicodeEscapes(raw, label); err != nil {
154			return nil, err
155		}
156		if err := rejectDuplicateFields(raw, label); err != nil {
157			return nil, err
158		}
159		doc, err := unmarshalStrictJSON(raw)
160		if err != nil {
161			return nil, fmt.Errorf("%s: invalid JSON: %w", label, err)
162		}
163		root, ok := doc.(map[string]any)
164		if !ok {
165			return nil, fmt.Errorf("%s: top level must be a JSON object", label)
166		}
167		return root, nil
168	}
169	
170	// ParseConfig parses a config document from JSON bytes with strict typing.
171	// 文档格式校验由 parseJSONDocument 与 ParseContext 共同维护；这里只继续处理
172	// 配置自身的业务字段（开关、规则、条件与唯一性）。先解析到 any 再逐字段校验，
173	// 以区分“字段缺失”与“显式提供的 false”。
174	func ParseConfig(raw []byte) (*Config, error) {
175		root, err := parseJSONDocument(raw, "config")
176		if err != nil {
177			return nil, err
178		}
179		flagsRaw, present := root["flags"]
180		if !present {
181			return nil, fmt.Errorf("config.flags: field is required")
182		}
183		if flagsRaw == nil {
184			return nil, fmt.Errorf("config.flags: must be an array, got null")
185		}
186		flagsArr, ok := flagsRaw.([]any)
187		if !ok {
188			return nil, fmt.Errorf("config.flags: must be an array")
189		}
190		cfg := &Config{}
191		seenKeys := map[string]int{}
192		for i, fr := range flagsArr {
193			flag, err := parseFlag(fr, i)
194			if err != nil {
195				return nil, err
196			}
197			if prev, dup := seenKeys[flag.Key]; dup {
198				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
199			}
200			seenKeys[flag.Key] = i
201			cfg.Flags = append(cfg.Flags, flag)
202		}
203		return cfg, nil
204	}
205	
206	// ParseContext parses an attribute-name -> string context object; it may be empty.
207	// 文档格式校验由 parseJSONDocument 与 ParseConfig 共同维护；这里只继续检查
208	// 上下文自身的业务规则：每个顶层属性的值都必须是字符串。
209	func ParseContext(raw []byte) (*Context, error) {
210		root, err := parseJSONDocument(raw, "context")
211		if err != nil {
212			return nil, err
213		}
214		// 语法校验通过后才建立可用属性：值类型检查与属性建立在同一次遍历中完成。
215		return buildContext(raw, root)
216	}
217	
218	// buildContext 按文件原文顺序做一次流式遍历，同时完成顶层属性的值类型检查
219	// 与可用属性的建立：字段名顺序取自令牌流（Go map 的遍历顺序不稳定，不能
220	// 直接 range root，否则同一文件在不同运行中可能报告不同属性），属性值复用
221	// 严格解码得出的 root——同一份上下文的值只解码一次。语法、重复字段与 Unicode
222	// 转义已在此前校验，这里的令牌读取不会再遇到错误。键名使用解码后的文字
223	// （合法的 \uXXXX 转义与直接字符同义；大小写与空白按原样保留）。对象或数组
224	// 值整体算所属顶层属性的一个值，错误不指向其内部成员。
225	func buildContext(raw []byte, root map[string]any) (*Context, error) {
226		dec := json.NewDecoder(bytes.NewReader(raw))
227		// 消费顶层对象的 '{'；语法已由 unmarshalStrictJSON 校验。
228		if _, err := dec.Token(); err != nil {
229			return nil, fmt.Errorf("context: invalid JSON: %w", err)
230		}
231		ctx := &Context{values: make(map[string]string, len(root))}
232		for dec.More() {
233			keyTok, err := dec.Token()
234			if err != nil {
235				return nil, fmt.Errorf("context: invalid JSON: %w", err)
236			}
237			key, _ := keyTok.(string)
238			// 值不再重复解码：RawMessage 只把读取位置推进到下一个字段，
239			// 实际值取自已严格解码的 root。数字（含超出浮点范围的 json.Number）、
240			// 布尔、null、对象、数组都在这里按所属属性报类型错误。
241			var skipped json.RawMessage
242			if err := dec.Decode(&skipped); err != nil {
243				return nil, fmt.Errorf("context: invalid JSON: %w", err)
244			}
245			s, ok := root[key].(string)
246			if !ok {
247				return nil, fmt.Errorf("%s: value must be a string", appendFieldPath("context", key))
248			}
249			ctx.values[key] = s
250		}
251		return ctx, nil
252	}
253	
254	// Get looks up an attribute; an empty string is a legal value.
255	func (c *Context) Get(attribute string) (string, bool) {
256		if c == nil {
257			return "", false
258		}
259		v, ok := c.values[attribute]
260		return v, ok
261	}
262	
263	// Find returns the flag with the given key, or nil if absent.
264	func (c *Config) Find(key string) *Flag {
265		if c == nil {
266			return nil
267		}
268		for i := range c.Flags {
269			if c.Flags[i].Key == key {
270				return &c.Flags[i]
271			}
272		}
273		return nil
274	}
275	
276	// Evaluate deterministically evaluates a flag against a context.
277	// 未启用固定 false（reason=disabled），不使用默认值或规则；启用后取首条
278	// 所有条件均成立的规则的 value；无匹配取 default。求值不依赖时间、随机数
279	// 或 map 遍历顺序，同一配置与上下文重复求值结果一致。
280	func (f *Flag) Evaluate(ctx *Context) EvalResult {
281		if !f.Enabled {
282			return EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil}
283		}
284		for i := range f.Rules {
285			rule := &f.Rules[i]
286			if rule.matches(ctx) {
287				id := rule.ID
288				return EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id}
289			}
290		}
291		return EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil}
292	}
293	
294	func (r *Rule) matches(ctx *Context) bool {
295		for i := range r.Conditions {
296			if !r.Conditions[i].matches(ctx) {
297				return false
298			}
299		}
300		return true
301	}
302	
303	func (c Condition) matches(ctx *Context) bool {
304		v, present := ctx.Get(c.Attribute)
305		if !present {
306			return false
307		}
308		switch c.Op {
309		case "eq":
310			return v == c.strVal
311		case "in":
312			for _, candidate := range c.inVal {
313				if v == candidate {
314					return true
315				}
316			}
317			return false
318		default:
319			// 解析阶段已拒绝未知运算符，防御性处理。
320			return false
321		}
322	}
323	
324	// MarshalResult renders the result as a single compact JSON object.
325	func MarshalResult(r EvalResult) ([]byte, error) {
326		var buf bytes.Buffer
327		enc := json.NewEncoder(&buf)
328		enc.SetEscapeHTML(false)
329		if err := enc.Encode(r); err != nil {
330			return nil, err
331		}
332		return bytes.TrimRight(buf.Bytes(), "\n"), nil
333	}
334	
335	// --- strict parsing helpers -------------------------------------------------
336	
337	// isSimpleFieldName 报告字段名是否走点号连接：以 ASCII 字母或下划线开头，
338	// 其后只能含 ASCII 字母、数字、下划线。其他任何名字（含点号、方括号、空白、
339	// 空名、非 ASCII 字符）都改用方括号包住的 JSON 字符串定位，如
340	// context["user.name"]、context[""]。
341	func isSimpleFieldName(name string) bool {
342		if name == "" {
343			return false
344		}
345		for i := 0; i < len(name); i++ {
346			c := name[i]
347			// 非 ASCII 字节（UTF-8 续字节或首字节）一律不满足“仅 ASCII”的要求。
348			if c >= 0x80 {
349				return false
350			}
351			ok := ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') || c == '_'
352			if i > 0 {
353				ok = ok || ('0' <= c && c <= '9')
354			}
355			if !ok {
356				return false
357			}
358		}
359		return true
360	}
361	
362	// appendFieldPath 在父位置后接上一个字段：简单字段名用点号连接，其余字段名
363	// 用方括号包住一个 JSON 字符串，引号、反斜杠与控制字符按 JSON 转义显示
364	// （Marshal 对 U+2028/U+2029 也会转义，但普通可见 Unicode 保持原样）。
365	// 名字按 JSON 解码后的文字传入，因此直接字符与合法 \uXXXX 转义得到同一位置。
366	func appendFieldPath(parent, name string) string {
367		if isSimpleFieldName(name) {
368			return parent + "." + name
369		}
370		return parent + "[" + jsonQuote(name) + "]"
371	}
372	
373	// jsonQuote 把字符串渲染为带双引号的 JSON 字符串字面量：引号、反斜杠与控制
374	// 字符按 JSON 转义（U+2028/U+2029 也会转义，避免定位文字被行分隔符拆行），
375	// 其余可见字符（含 <>& 与非 ASCII 文字）保持原样。
376	func jsonQuote(s string) string {
377		var buf bytes.Buffer
378		enc := json.NewEncoder(&buf)
379		enc.SetEscapeHTML(false)
380		if err := enc.Encode(s); err != nil {
381			// 不会发生：string 的 JSON 编码没有失败路径；保留一个确定的退路。
382			return strconv.Quote(s)
383		}
384		return string(bytes.TrimRight(buf.Bytes(), "\n"))
385	}
386	
387	// jsonFrame 是 JSON 原文遍历中一个对象或数组的层级状态。重复字段检查与非法
388	// Unicode 转义检查共用这一份层级与位置定义，调整错误定位时只需改这一处。
389	type jsonFrame struct {
390		path   string // 容器自身的完整位置，如 config.flags[0].rules[1]
391		object bool
392		// keys 记录本对象已声明的字段名（按解码后的字符串），仅重复字段检查使用；
393		// Unicode 遍历不登记字段，保持 nil。
394		keys map[string]struct{}
395		// lastKey 是对象最近一个字段名，用于拼出字段值的位置。
396		lastKey string
397		// expectKey 标记对象内下一个字符串是否为字段名。
398		expectKey bool
399		// nextIndex 是数组下一个元素的下标。
400		nextIndex int
401	}
402	
403	// jsonPathTracker 是两类 JSON 检查共用的对象层级、数组位置与字段路径状态机。
404	// label 是根容器的位置前缀（"config" 或 "context"）。
405	type jsonPathTracker struct {
406		label string
407		stack []*jsonFrame
408	}
409	
410	func newJSONPathTracker(label string) *jsonPathTracker {
411		return &jsonPathTracker{label: label}
412	}
413	
414	func (t *jsonPathTracker) top() *jsonFrame {
415		return t.stack[len(t.stack)-1]
416	}
417	
418	// childPath 拼出栈顶容器内下一个子值的位置：对象的字段值按 appendFieldPath
419	// 规则连接（简单名用点号，其余用方括号 JSON 字符串），数组元素用 [下标]。
420	func (t *jsonPathTracker) childPath() string {
421		top := t.top()
422		if top.object {
423			return appendFieldPath(top.path, top.lastKey)
424		}
425		return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
426	}
427	
428	// beginContainer 在遇到 '{' 或 '[' 时压入新容器，返回新容器的完整位置。
429	func (t *jsonPathTracker) beginContainer(object bool) string {
430		path := t.label
431		if len(t.stack) > 0 {
432			path = t.childPath()
433		}
434		t.stack = append(t.stack, &jsonFrame{path: path, object: object, expectKey: object})
435		return path
436	}
437	
438	// endContainer 在遇到 '}' 或 ']' 时弹出容器，并把整个容器计为父容器中
439	// 一个已完成的值。
440	func (t *jsonPathTracker) endContainer() {
441		if len(t.stack) > 0 {
442			t.stack = t.stack[:len(t.stack)-1]
443		}
444		t.endValue()
445	}
446	
447	// atKey 报告下一个字符串是否应按对象字段名处理。
448	func (t *jsonPathTracker) atKey() bool {
449		return len(t.stack) > 0 && t.top().object && t.top().expectKey
450	}
451	
452	// currentPath 返回当前容器自身的位置（字段名报错时指向所属对象）；
453	// 栈为空时返回根标签。
454	func (t *jsonPathTracker) currentPath() string {
455		if len(t.stack) == 0 {
456			return t.label
457		}
458		return t.top().path
459	}
460	
461	// valuePath 拼出下一个字符串值（字段值或数组元素）的位置，但不改变状态。
462	func (t *jsonPathTracker) valuePath() string {
463		if len(t.stack) == 0 {
464			return t.label
465		}
466		return t.childPath()
467	}
468	
469	// endValue 在一个字段值或数组元素完成后调用：对象回到等待字段名的状态，
470	// 数组推进元素下标。
471	func (t *jsonPathTracker) endValue() {
472		if len(t.stack) == 0 {
473			return
474		}
475		top := t.top()
476		if top.object {
477			top.expectKey = true
478		} else {
479			top.nextIndex++
480		}
481	}
482	
483	// noteKey 登记一个已解码的对象字段名：更新字段路径状态，并在同一对象内第二次
484	// 声明同名字段时返回重复字段错误。
485	func (t *jsonPathTracker) noteKey(name string) error {
486		top := t.top()
487		if top.keys == nil {
488			top.keys = make(map[string]struct{})
489		}
490		if _, dup := top.keys[name]; dup {
491			return fmt.Errorf("%s: duplicate field %s", appendFieldPath(top.path, name), jsonQuote(name))
492		}
493		top.keys[name] = struct{}{}
494		top.lastKey = name
495		top.expectKey = false
496		return nil
497	}
498	
499	// setKey 在不做重复检查的遍历（Unicode 扫描）中记录一个成功解码的字段名，
500	// 仅维护字段值路径所需的状态。
501	func (t *jsonPathTracker) setKey(name string) {
502		top := t.top()
503		top.lastKey = name
504		top.expectKey = false
505	}
506	
507	// noteInvalidKey 在字段名无法解码（属于 JSON 语法错误）时仅推进键值状态：
508	// 不覆盖已记录的字段名；语法错误留给后续严格 JSON 解码报告。
509	func (t *jsonPathTracker) noteInvalidKey() {
510		t.top().expectKey = false
511	}
512	
513	// rejectDuplicateFields 按文件原文顺序扫描 JSON 令牌流，拒绝任何在同一对象内
514	// 重复声明的字段名。字段名按解码后的字符串比较（"enabled" 与 "énabled"
515	// 同名），大小写不同仍是不同字段，名字中的空白不裁剪。检查覆盖所有对象，
516	// 包括附加字段里嵌套的对象；数组元素不属于这一检查。label 是根对象的位置
517	// 前缀（"config" 或 "context"）。对象层级、数组下标与字段路径由
518	// jsonPathTracker 统一维护。JSON 语法错误不在此报告（令牌流失效即停止），
519	// 留给严格 JSON 解码。
520	func rejectDuplicateFields(raw []byte, label string) error {
521		dec := json.NewDecoder(bytes.NewReader(raw))
522		// UseNumber：数字以 json.Number 令牌返回而不转 float64，否则超出浮点范围
523		// 的合法数字（如 1e400）会让令牌流提前报错并中止，遮住其后的重复字段。
524		dec.UseNumber()
525		tracker := newJSONPathTracker(label)
526		for {
527			tok, err := dec.Token()
528			if err != nil {
529				// io.EOF 或语法错误；语法错误由后续严格 JSON 解码报告。
530				break
531			}
532			switch t := tok.(type) {
533			case json.Delim:
534				switch t {
535				case '{':
536					tracker.beginContainer(true)
537				case '[':
538					tracker.beginContainer(false)
539				case '}', ']':
540					tracker.endContainer()
541				}
542			case string:
543				if tracker.atKey() {
544					if err := tracker.noteKey(t); err != nil {
545						return err
546					}
547				} else {
548					tracker.endValue()
549				}
550			default:
551				tracker.endValue()
552			}
553		}
554		return nil
555	}
556	
557	// rejectInvalidUnicodeEscapes 按文件原文顺序扫描 JSON 文本，拒绝任何不能组成
558	// 完整字符的 \uXXXX 转义：孤立的高代理项、孤立的低代理项，以及不完整或顺序
559	// 错误的代理项对。encoding/json 解码时会把这类转义静默替换为 U+FFFD，使非法
560	// 输入与真正的 "�" 被当作相同字符串参与求值，或让字段名在替换后被误判为重复，
561	// 因此必须在解码前按原文拒绝。检查覆盖字段名与所有字符串值（包括规则的比较值、
562	// in 列表元素以及附加字段里的字符串），一个文件有多个问题时报告原文中最先出现
563	// 的一处。label 是根对象的位置前缀（"config" 或 "context"）。对象层级、数组
564	// 下标与字段路径由 jsonPathTracker 统一维护；JSON 语法错误不在此报告，留给
565	// Unmarshal。
566	func rejectInvalidUnicodeEscapes(raw []byte, label string) error {
567		tracker := newJSONPathTracker(label)
568		i := 0
569		for i < len(raw) {
570			c := raw[i]
571			switch {
572			case c == '{' || c == '[':
573				tracker.beginContainer(c == '{')
574				i++
575			case c == '}' || c == ']':
576				tracker.endContainer()
577				i++
578			case c == '"':
579				end := jsonStringEnd(raw, i)
580				contentEnd := end
581				if contentEnd > i+1 && raw[contentEnd-1] == '"' {
582					contentEnd-- // 去掉右引号；未终止的字符串留给严格 JSON 解码报告
583				}
584				content := raw[i+1 : contentEnd]
585				if tracker.atKey() {
586					if bad := findBadUnicodeEscape(content); bad != nil {
587						return fmt.Errorf("%s: field name %q contains invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
588							tracker.currentPath(), string(content), bad.escape, bad.detail)
589					}
590					// 转义已校验合法，解码用于定位路径；失败说明是语法错误，留给严格 JSON 解码。
591					if name, ok := decodeJSONString(raw[i:end]); ok {
592						tracker.setKey(name)
593					} else {
594						tracker.noteInvalidKey()
595					}
596				} else {
597					path := tracker.valuePath()
598					if bad := findBadUnicodeEscape(content); bad != nil {
599						return fmt.Errorf("%s: invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
600							path, bad.escape, bad.detail)
601					}
602					tracker.endValue()
603				}
604				i = end
605			case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ':' || c == ',':
606				i++
607			default:
608				// 数字与 true/false/null 等标量：跳过至下一个结构字符，按一个值计。
609				for i < len(raw) && !isJSONStructural(raw[i]) {
610					i++
611				}
612				tracker.endValue()
613			}
614		}
615		return nil
616	}
617	
618	// decodeJSONString 解码一个完整的 JSON 字符串字面量（含两侧引号）；ok 为 false
619	// 表示字面量本身非法（未终止或转义写法错误等），属于 JSON 语法错误。
620	func decodeJSONString(lit []byte) (s string, ok bool) {
621		if err := json.Unmarshal(lit, &s); err != nil {
622			return "", false
623		}
624		return s, true
625	}
626	
627	// badEscape 描述一处不能组成完整字符的 \uXXXX 转义。
628	type badEscape struct {
629		escape string // 原文中的转义序列，如 \uD800
630		detail string // 具体问题（孤立高代理项/孤立低代理项）
631	}
632	
633	// jsonStringEnd 返回从 raw[i]（必须是 '"'）开始的字符串字面量结束位置
634	// （右引号之后的下标）；未终止时返回 len(raw)。
635	func jsonStringEnd(raw []byte, i int) int {
636		j := i + 1
637		for j < len(raw) {
638			switch raw[j] {
639			case '\\':
640				j += 2
641			case '"':
642				return j + 1
643			default:
644				j++
645			}
646		}
647		return len(raw)
648	}
649	
650	// findBadUnicodeEscape 在字符串内容（不含引号）中查找第一处不能组成完整
651	// 字符的 \uXXXX 转义；没有则返回 nil。反斜杠本身的转义（\\）先于 \u 判定，
652	// 因此 "\\uD800" 只是普通文本。非法的 \u 写法（非 4 位十六进制）属于 JSON
653	// 语法错误，不在此报告。
654	func findBadUnicodeEscape(content []byte) *badEscape {
655		j := 0
656		for j < len(content) {
657			if content[j] != '\\' {
658				j++
659				continue
660			}
661			if j+1 >= len(content) {
662				break
663			}
664			if content[j+1] != 'u' {
665				j += 2
666				continue
667			}
668			if j+6 > len(content) || !isHex4(content[j+2:j+6]) {
669				j += 2
670				continue
671			}
672			cp := hexVal4(content[j+2 : j+6])
673			switch {
674			case cp >= 0xD800 && cp <= 0xDBFF:
675				// 高代理项只有紧跟一个低代理项转义才组成完整字符。
676				if j+12 <= len(content) && content[j+6] == '\\' && content[j+7] == 'u' &&
677					isHex4(content[j+8:j+12]) {
678					if lo := hexVal4(content[j+8 : j+12]); lo >= 0xDC00 && lo <= 0xDFFF {
679						j += 12
680						continue
681					}
682				}
683				return &badEscape{
684					escape: string(content[j : j+6]),
685					detail: "high surrogate is not followed by a low surrogate",
686				}
687			case cp >= 0xDC00 && cp <= 0xDFFF:
688				return &badEscape{
689					escape: string(content[j : j+6]),
690					detail: "low surrogate is not preceded by a high surrogate",
691				}
692			}
693			j += 6
694		}
695		return nil
696	}
697	
698	// isJSONStructural 报告 b 是否为 JSON 结构字符或空白（标量值的边界）。
699	func isJSONStructural(b byte) bool {
700		switch b {
701		case ' ', '\t', '\n', '\r', '{', '}', '[', ']', ':', ',', '"':
702			return true
703		}
704		return false
705	}
706	
707	// isHex4 报告 b 是否恰好为 4 个十六进制数字。
708	func isHex4(b []byte) bool {
709		if len(b) != 4 {
710			return false
711		}
712		for _, c := range b {
713			if !isHexDigit(c) {
714				return false
715			}
716		}
717		return true
718	}
719	
720	func isHexDigit(c byte) bool {
721		return ('0' <= c && c <= '9') || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F')
722	}
723	
724	// hexVal4 把 4 个十六进制数字解析为码点值；调用前须先经 isHex4 校验。
725	func hexVal4(b []byte) int {
726		v := 0
727		for _, c := range b {
728			v <<= 4
729			switch {
730			case '0' <= c && c <= '9':
731				v |= int(c - '0')
732			case 'a' <= c && c <= 'f':
733				v |= int(c-'a') + 10
734			default: // 'A' <= c && c <= 'F'
735				v |= int(c-'A') + 10
736			}
737		}
738		return v
739	}
740	
741	func parseFlag(raw any, index int) (Flag, error) {
742		loc := fmt.Sprintf("config.flags[%d]", index)
743		obj, ok := raw.(map[string]any)
744		if !ok {
745			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
746		}
747		key, err := requireNonEmptyString(obj, "key", loc)
748		if err != nil {
749			return Flag{}, err
750		}
751		enabled, err := requireBool(obj, "enabled", loc)
752		if err != nil {
753			return Flag{}, err
754		}
755		def, err := requireBool(obj, "default", loc)
756		if err != nil {
757			return Flag{}, err
758		}
759		rulesArr, err := requireArrayField(obj, "rules", loc)
760		if err != nil {
761			return Flag{}, err
762		}
763		flag := Flag{Key: key, Enabled: enabled, Default: def}
764		seenRules := map[string]int{}
765		for ri, rv := range rulesArr {
766			rule, err := parseRule(rv, index, ri)
767			if err != nil {
768				return Flag{}, err
769			}
770			if prev, dup := seenRules[rule.ID]; dup {
771				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
772			}
773			seenRules[rule.ID] = ri
774			flag.Rules = append(flag.Rules, rule)
775		}
776		return flag, nil
777	}
778	
779	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
780		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
781		obj, ok := raw.(map[string]any)
782		if !ok {
783			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
784		}
785		id, err := requireNonEmptyString(obj, "id", loc)
786		if err != nil {
787			return Rule{}, err
788		}
789		value, err := requireBool(obj, "value", loc)
790		if err != nil {
791			return Rule{}, err
792		}
793		condsArr, err := requireArrayField(obj, "conditions", loc)
794		if err != nil {
795			return Rule{}, err
796		}
797		if len(condsArr) == 0 {
798			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
799		}
800		rule := Rule{ID: id, Value: value}
801		for ci, cv := range condsArr {
802			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
803			if err != nil {
804				return Rule{}, err
805			}
806			rule.Conditions = append(rule.Conditions, cond)
807		}
808		return rule, nil
809	}
810	
811	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
812		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
813		obj, ok := raw.(map[string]any)
814		if !ok {
815			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
816		}
817		attribute, err := requireNonEmptyString(obj, "attribute", loc)
818		if err != nil {
819			return Condition{}, err
820		}
821		op, err := requireNonEmptyString(obj, "op", loc)
822		if err != nil {
823			return Condition{}, err
824		}
825		valueField, err := requireField(obj, "value", loc)
826		if err != nil {
827			return Condition{}, err
828		}
829		cond := Condition{Attribute: attribute, Op: op}
830		switch op {
831		case "eq":
832			s, ok := valueField.(string)
833			if !ok {
834				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
835			}
836			cond.strVal = s
837		case "in":
838			arr, ok := valueField.([]any)
839			if !ok {
840				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
841			}
842			if len(arr) == 0 {
843				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
844			}
845			for ii, item := range arr {
846				s, ok := item.(string)
847				if !ok {
848					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
849				}
850				cond.inVal = append(cond.inVal, s)
851			}
852		default:
853			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
854		}
855		return cond, nil
856	}
857	
858	func requireField(obj map[string]any, name, loc string) (any, error) {
859		v, ok := obj[name]
860		if !ok {
861			return nil, fmt.Errorf("%s: field is required", appendFieldPath(loc, name))
862		}
863		if v == nil {
864			return nil, fmt.Errorf("%s: must not be null", appendFieldPath(loc, name))
865		}
866		return v, nil
867	}
868	
869	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
870		v, err := requireField(obj, name, loc)
871		if err != nil {
872			return nil, err
873		}
874		arr, ok := v.([]any)
875		if !ok {
876			return nil, fmt.Errorf("%s: must be an array", appendFieldPath(loc, name))
877		}
878		return arr, nil
879	}
880	
881	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
882		v, err := requireField(obj, name, loc)
883		if err != nil {
884			return "", err
885		}
886		s, ok := v.(string)
887		if !ok {
888			return "", fmt.Errorf("%s: must be a string", appendFieldPath(loc, name))
889		}
890		if s == "" {
891			return "", fmt.Errorf("%s: must not be empty", appendFieldPath(loc, name))
892		}
893		return s, nil
894	}
895	
896	func requireBool(obj map[string]any, name, loc string) (bool, error) {
897		v, err := requireField(obj, name, loc)
898		if err != nil {
899			return false, err
900		}
901		b, ok := v.(bool)
902		if !ok {
903			return false, fmt.Errorf("%s: must be a boolean", appendFieldPath(loc, name))
904		}
905		return b, nil
906	}
